// Initialize / normalize task state
const body = $json.body || $json;
const taskId = body.taskId || `TASK-${Date.now().toString(36).toUpperCase()}`;
const state = {
  taskId,
  runId: crypto.randomUUID(),
  attempt: body.attempt || 1,
  status: 'PLANNING',
  task_description: body.task || body.description || '',
  branch: `agent/${taskId}`,
  timestamp: new Date().toISOString(),
  max_attempts: 10
};
return [{ json: state }];

// Merge architect output into task state (OpenAI HTTP Request response shape)
const state = $items('Task State', 0, 0)[0].json;
let spec;
try {
  const raw = $json.choices?.[0]?.message?.content || $json.message?.content || $json.text || $json;
  spec = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  throw new Error('Architect returned non-JSON: ' + (e.message));
}
return [{ json: { ...state, status: 'IMPLEMENTING', spec } }];

// Preserve task state alongside runner output
const state = $items('Merge Spec', 0, 0)[0].json;
const runner = $json;
if (!runner.ok) {
  return [{ json: { ...state, status: 'FAILED', runner } }];
}
return [{ json: {
  ...state,
  status: 'WAITING_REVIEW',
  branch: runner.branch,
  commit: runner.commit,
  pr: runner.pr,
  tests: runner.tests,
  claudeReport: runner.claudeReport,
  diff_stat: runner.diff_stat
} }];

// Parse reviewer JSON from OpenAI HTTP Request response
const state = $items('Merge Runner Result', 0, 0)[0].json;
let decision;
try {
  const raw = $json.choices?.[0]?.message?.content || $json.message?.content || $json.text || $json;
  decision = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  throw new Error('Reviewer returned non-JSON: ' + e.message);
}
const approved = decision.decision === 'APPROVED';
return [{ json: { ...state, status: approved ? 'APPROVED' : 'CHANGES_REQUIRED', decision, approved_for_deploy: !!decision.approved_for_deploy, feedback: decision.feedback || null } }];

// Approved path: build final report artefact
const r = {
  status: 'DONE',
  taskId: $json.taskId, runId: $json.runId,
  branch: $json.branch, commit: $json.commit,
  pr: $json.pr,
  attempts: $json.attempt,
  approved_for_deploy: !!$json.approved_for_deploy,
  summary: $json.decision?.summary || ''
};
return [{ json: r }];

// Placeholder for Railway redeploy. Requires manual approval by design;
// this node deliberately does not run any command until the deploy gate
// is intentionally wired to a credentialed HTTP call.
return [{ json: { ...$json, deploy: 'SKIPPED_BY_DESIGN', note: 'Deploy step disabled until an operator wires this node to Railway.' } }];
